html:
{% set highlighted_rows = ["Total Fixed Salary", "Total Benefits", "CTC", "Total Deductions", "Net Salary"] %}
{% set section_headers = ["Deductions"] %}

<style>
    * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }

    body {
        font-family: Arial, sans-serif;
        font-size: 12px;
        color: #000;
        line-height: 1.5;
    }

    .page1 {
        padding: 0 10px;
    }

    .offer-title {
        text-align: center;
        font-size: 17px;
        font-weight: bold;
        margin-bottom: 28px;
        letter-spacing: 2px;
        text-decoration: underline;
    }

    .date-line {
        text-align: right;
        font-weight: bold;
        margin-bottom: 18px;
    }

    .greeting {
        font-weight: bold;
        margin-bottom: 14px;
        line-height: 2;
    }

    .intro-para {
        margin-bottom: 12px;
        line-height: 1.7;
    }

    table.salary-table {
        width: 100%;
        border-collapse: collapse;
        margin: 14px 0 8px 0;
    }

    .salary-table th,
    .salary-table td {
        border: 1px solid #000;
        padding: 6px 10px;
    }

    .salary-table th {
        background-color: #F5C518;
        font-weight: bold;
        text-align: left;
    }

    .salary-table td:first-child {
        text-align: left;
        width: 55%;
    }

    .salary-table td:not(:first-child) {
        text-align: right;
        width: 22.5%;
    }

    .row-highlighted td {
        background-color: #F5C518;
        font-weight: bold;
    }

    .row-section-header td {
        background-color: #F5C518;
        font-weight: bold;
    }

    .row-section-header td:not(:first-child) {
        text-align: right;
    }

    .footnotes {
        font-size: 11px;
        line-height: 2;
        margin-top: 6px;
    }

    /* ---- Page 2 ---- */
    .page2 {
        page-break-before: always;
        padding: 0 10px;
    }

    .terms-content {
        line-height: 1.6;
    }

    .terms-content p {
        margin-bottom: 6px;
        text-align: justify;
    }

    .terms-content ol {
        margin: 0 0 6px 18px;
    }

    .terms-content li {
        margin-bottom: 2px;
        line-height: 1.5;
    }

    .sig-section {
        margin-top: 12px;
        line-height: 2;
    }

    .acceptance {
        margin-top: 16px;
    }

    .acceptance > p {
        margin-bottom: 4px;
        line-height: 1.6;
    }

    .acceptance-line {
        font-weight: bold;
        margin-top: 14px;
    }

    .sig-blank {
        display: inline-block;
        width: 280px;
        border-bottom: 1px solid #000;
    }
</style>

<!-- ========== PAGE 1 ========== -->
<div class="page1">
    <div class="offer-title">OFFER LETTER</div>

    <div class="date-line">Date: {{ doc.offer_date }}</div>

    <div class="greeting">
        To,<br>
        Dear {{ doc.applicant_name }},
    </div>

    <p class="intro-para">
        We are pleased to offer you in {{ doc.company }} as
        <strong>{{ doc.designation }}</strong>
        {% if doc.department %}
            in <strong>{{ doc.department }}</strong> Department
        {% endif %}.
    </p>

    <p class="intro-para">Below are your offer details.</p>

    <table class="salary-table">
        <thead>
            <tr>
                <th style="width:55%">Components</th>
                <th style="width:22.5%; text-align:right">Per month</th>
                <th style="width:22.5%; text-align:right">Per Annum</th>
            </tr>
        </thead>
        <tbody>
            {% for row in doc.offer_terms %}
                {% if row.offer_term in section_headers %}
                    <tr class="row-section-header">
                        <td><strong>{{ row.offer_term }}</strong></td>
                        <td style="text-align:right"><strong>Per month</strong></td>
                        <td style="text-align:right"><strong>Per Annum</strong></td>
                    </tr>
                {% elif row.offer_term in highlighted_rows %}
                    <tr class="row-highlighted">
                        <td><strong>{{ row.offer_term }}</strong></td>
                        <td>{{ row.value or "" }}</td>
                        <td>{{ row.per_annum or "" }}</td>
                    </tr>
                {% else %}
                    <tr>
                        <td>{{ row.offer_term }}</td>
                        <td>{{ row.value or "" }}</td>
                        <td>{{ row.per_annum or "" }}</td>
                    </tr>
                {% endif %}
            {% endfor %}
        </tbody>
    </table>

    <div class="footnotes">
        * Bonus if applicable is given either before Diwali or employee exit.<br>
        * Mediclaim if applicable, +/-50% every year.<br>
        * GPA - +/-20% every year
    </div>
</div>

<!-- ========== PAGE 2 ========== -->
<div class="page2">

    {% if doc.terms %}
    <div class="terms-content">
        {{ doc.terms | safe }}
    </div>
    {% endif %}

    <div class="sig-section">
        <p>Sincerely:</p>
        <br>
        <p><strong>For {{ doc.company }}</strong></p>
        <br><br>
        <p><strong>Authorised Signatory</strong></p>
    </div>

    <div class="acceptance">
        <p>I accept this action as outlined above and confirm that my start date is:</p>

        <div class="acceptance-line">
            Signature: &nbsp;<span class="sig-blank">&nbsp;</span>
        </div>

        <div class="acceptance-line">
            Name: &nbsp;&nbsp;&nbsp;&nbsp;<span class="sig-blank">&nbsp;</span>
        </div>

        <div class="acceptance-line">
            Date: &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sig-blank">&nbsp;</span>
        </div>
    </div>
</div>

{% set total_rows = ["Net in Hand", "CTC"] %}

