        text-align: left;
    }

    .salary-table td:first-child {
        text-align: left;
        width: 55%;
    }

    .salary-table td:not(:first-child) {
        text-align: right;
        width: 22.5%;
    }

    .salary-table.two-col td:first-child,
    .salary-table.two-col th:first-child {
        width: 70%;
    }

    .salary-table.two-col td:not(:first-child),
    .salary-table.two-col th:not(:first-child) {
        width: 30%;
    }

    .row-highlighted td {
        background-color: #F5C518;
        font-weight: bold;
    }

    .row-section-header td {
        background-color: #F5C518;
        font-weight: bold;
    }

    .row-section-header td:not(:first-child) {
        text-align: right;
    }

