        margin-bottom: 4px;
        line-height: 1.6;
    }

    .acceptance-line {
        font-weight: bold;
        margin-top: 14px;
    }

    .sig-blank {
        display: inline-block;
        width: 280px;
        border-bottom: 1px solid #000;
    }
</style>

<!-- ========== PAGE 1 ========== -->
<div class="page1">
    <div class="offer-title">APPOINTMENT LETTER</div>

    <div class="date-line">Date: {{ frappe.utils.formatdate(doc.appointment_date, "dd-MM-yyyy") }}</div>

    <div class="greeting">
        To,<br>
        Employee Name: <strong>{{ doc.applicant_name }}</strong><br>
        Mob No: {{ frappe.db.get_value("Job Applicant", doc.job_applicant, "phone_number") or "" }}
    </div>

    <div class="greeting">
        Dear {{ doc.applicant_name }},
    </div>

    {% if doc.introduction %}
    <div class="intro-para">{{ doc.introduction | safe }}</div>
    {% endif %}

    {% if doc.closing_notes %}
    <div class="intro-para">{{ doc.closing_notes | safe }}</div>
    {% endif %}

    <div class="sig-section">
        <p>For <strong>{{ doc.company }}</strong></p>
        <br><br>
        <p><strong>Authorised Signatory</strong></p>
    </div>

    <div class="footnotes">Accepted &amp; Agreed</div>
</div>

<!-- ========== PAGE 2 ========== -->
<div class="page2">

    <div class="acceptance">
        <div class="acceptance-line">
            Signature: &nbsp;<span class="sig-blank">&nbsp;</span>
        </div>

        <div class="acceptance-line">
            Name: &nbsp;&nbsp;&nbsp;&nbsp;<strong>{{ doc.applicant_name }}</strong>
        </div>

        <div class="acceptance-line">
            Date: &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sig-blank">&nbsp;</span>
        </div>
    </div>

    <div class="offer-title" style="margin-top: 28px;">ANNEXURE</div>

    <div class="name-date-row">
        <span>Name: <strong>{{ doc.applicant_name }}</strong></span>
        <span>Date: <strong>{{ frappe.utils.formatdate(doc.appointment_date, "dd-MM-yyyy") }}</strong></span>
    </div>

    <table class="salary-table two-col">
        <thead>
            <tr>
                <th>Description</th>
                <th style="text-align:right">Amt/Month</th>
            </tr>
        </thead>
        <tbody>
            {% for term in doc.terms %}
                {% if not term.description or term.description.strip() == "" %}
                    <tr class="row-section-header">
                        <td colspan="2"><strong>{{ term.title }}</strong></td>
                    </tr>
                {% elif term.title in total_rows %}
                    <tr class="row-highlighted">
                        <td><strong>{{ term.title }}</strong></td>
                        <td>{{ term.description }}</td>
                    </tr>
                {% else %}
                    <tr>
                        <td>{{ term.title }}</td>
                        <td>{{ term.description }}</td>
                    </tr>
                {% endif %}
            {% endfor %}
        </tbody>
    </table>

    <div class="footnotes">Full bonus will be given at the time of Diwali.</div>

    <div class="sig-section">
        <p>For <strong>{{ doc.company }}</strong></p>
        <br><br>
        <p><strong>Authorised Signatory</strong></p>
    </div>

    <div class="acceptance">
        <p><strong>Accepted and Acknowledged</strong></p>
    </div>
</div>
